static inline bool ovl_should_lock_real_pos(struct file *realfile)
{
	/*
	 * We need to hold f_pos_lock if the file is one of those that
	 * require it (e.g. FMODE_ATOMIC_POS or directories with iterate_shared).
	 * We can't use the VFS helper file_needs_f_pos_lock() because it is
	 * private to fs/file.c.
	 */
	return (realfile->f_mode & FMODE_ATOMIC_POS) ||
	       realfile->f_op->iterate_shared;
}

